// Selects authored explanations directly from verified subject state. Unlike the
// archive fallback, these passages explain what a value means and relate it to
// current behaviour without predicting an unsupported outcome.
export function deterministicPhysiologyPassage(context = {}) {
  const subject = context.subjects?.[0]; if (!subject) return null;
  const p = phrase(subject), candidates = [], recent = new Set(context.narrativeMemory?.recentTopics || []);
  const aerobic = number(subject.aerobicHeadroom), burst = number(subject.burstReserve), burden = number(subject.recoveryBurden), aerobicLoad = number(subject.aerobicLoad), muscular = number(subject.muscularLoad), anaerobic = number(subject.anaerobicDebt), stress = number(subject.stressIntensity), stressDebt = number(subject.stressRecoveryDebt);
  if (subject.performanceZone) candidates.push(candidate(108, `physiology:${subject.id}:zone:${subject.performanceZone}`, `${p} is working in the ${tidy(subject.performanceZone)} performance zone. The requested pace is ${tidy(subject.requestedPace || "unknown")}, while ${tidy(subject.affordablePace || "the present pace")} is currently affordable. The distinction shows whether this movement can be repeated or must be repaid through recovery.`, "How long can the current performance zone be maintained?", "A shift to a lower affordable pace may preserve the current objective."));
  if (aerobic !== null && aerobic < 55) candidates.push(candidate(112 - aerobic / 5, `physiology:${subject.id}:aerobic:${band(aerobic)}`, `${p} has ${band(aerobic)} aerobic headroom. This limits sustained pace, but it does not by itself remove the ability to keep travelling more slowly.`, "Will the animal reduce pace before travel becomes unavailable?", "A slower pace may allow the same objective to continue."));
  if (burst !== null && burst < 70) candidates.push(candidate(110 - burst / 8, `physiology:${subject.id}:burst:${band(burst)}`, `${p} has ${band(burst)} burst capacity. Sprinting, flight or combat will draw from that rapid muscular reserve; ordinary walking need not.`, "Will another urgent event arrive before burst capacity is restored?", "Limited burst reserve may favour slower movement until a credible emergency appears."));
  if (burden !== null && burden > 20) candidates.push(candidate(106 + burden / 10, `physiology:${subject.id}:recovery:${band(burden)}:${subject.recoveryDepth}`, `${p} is carrying ${band(burden)} recovery burden and is presently in ${tidy(subject.recoveryDepth || "no dedicated recovery")} state. The recommended depth is ${tidy(subject.recommendedRecovery || "not yet determined")}, based upon the kind of debt rather than one universal fatigue score.`, "Can sufficient safety be found for the recommended recovery depth?", "The selected recovery depth may trade detection range for faster restoration."));
  if (aerobicLoad !== null && muscular !== null && (aerobicLoad > 25 || muscular > 25)) candidates.push(candidate(104 + Math.max(aerobicLoad, muscular) / 12, `physiology:${subject.id}:loads:${band(aerobicLoad)}:${band(muscular)}`, `${p} carries ${band(aerobicLoad)} aerobic load and ${band(muscular)} muscular load. Prolonged travel and a short burst have therefore left different physical accounts, even when both appear simply as movement.`, "Which form of recovery will become limiting first?", "The larger load may determine whether active or deeper recovery is selected."));
  if (anaerobic !== null && anaerobic > 12) candidates.push(candidate(107 + anaerobic / 12, `physiology:${subject.id}:anaerobic:${band(anaerobic)}`, `${p} retains ${band(anaerobic)} anaerobic debt from work above its sustainable range. Light activity or rest can clear that debt, but another burst begun now would start from an incomplete recovery.`, "Will the interval before the next burst be long enough?", "Continued low-intensity movement may clear debt while preserving awareness."));
  if (subject.stressState && subject.stressState !== "calm" && subject.stressState !== "idle") candidates.push(candidate(116, `physiology:${subject.id}:stress:${subject.stressState}:${band(stress || 0)}`, `${p} is in a ${tidy(subject.stressState)} stress state at ${band(stress || 0)} intensity. The response can mobilise existing fuel and relax voluntary limits, but it cannot create energy.`, "When danger recedes, how much stress debt will remain?", "Repeated activation may extend the recovery required after the immediate event."));
  if (stressDebt !== null && stressDebt > 15) candidates.push(candidate(105 + stressDebt / 12, `physiology:${subject.id}:stress-debt:${band(stressDebt)}`, `${p} carries ${band(stressDebt)} stress-recovery debt. The visible threat may have ended, yet digestion, attention and physical readiness have not returned immediately to baseline.`, "Will a quiet interval allow the stress response to settle?", "Further disturbance may compound recovery debt before it clears."));
  return candidates.filter(item => !recent.has(item.key)).sort((a, b) => b.score - a.score)[0] || null;
}

export function deterministicPlanningPassage(context = {}) {
  const subject = context.subjects?.[0]; if (!subject) return null;
  const p = phrase(subject), candidates = [], recent = new Set(context.narrativeMemory?.recentTopics || []), plan = subject.needSatisfier || {}, audit = subject.needAudit || {};
  if (subject.priority && (subject.satisfier || plan.satisfierId || plan.method)) { const method = tidy(subject.satisfier || plan.satisfierId || plan.method); candidates.push(candidate(102, `planning:${subject.id}:${tidy(subject.priority)}:${method}`, `${p} has ${tidy(subject.priority)} as its recorded priority and is using ${method} as the proposed satisfier. The method can change if evidence fails without making the underlying need disappear.`, "Will the selected satisfier remain viable through contact and use?", "Failure evidence may change the method while preserving the same need.")); }
  if (subject.commitmentStatus || subject.commitmentProgress != null) candidates.push(candidate(96, `planning:${subject.id}:commitment:${subject.commitmentStatus}:${Math.round(Number(subject.commitmentProgress || 0) * 5)}`, `${p} is ${tidy(subject.commitmentStatus || "maintaining a commitment")} with recorded progress at ${Math.round(Number(subject.commitmentProgress || 0) * 100)} per cent. Commitment protects a viable plan from minor fluctuations, but urgent danger can still override it.`, "Will new evidence strengthen the commitment or force reconsideration?", "Continued progress may preserve the incumbent plan unless a survival emergency intervenes."));
  if (audit.need || audit.phase || audit.reason) candidates.push(candidate(92, `planning:${subject.id}:audit:${tidy(audit.need)}:${tidy(audit.phase)}`, `${p}'s decision audit identifies ${tidy(audit.need || subject.priority || "a current need")} during ${tidy(audit.phase || plan.phase || "the present phase")}. ${tidy(audit.reason || "The simulation retains why this action was selected rather than presenting it as an unexplained impulse.")}`, "What evidence will complete or invalidate this phase?", "A stalled phase may trigger reassessment before the whole objective is abandoned."));
  return candidates.filter(item => !recent.has(item.key)).sort((a, b) => b.score - a.score)[0] || null;
}

export function deterministicSocialPassage(context = {}) {
  const subject = context.subjects?.[0]; if (!subject) return null;
  const p = phrase(subject), candidates = [], recent = new Set(context.narrativeMemory?.recentTopics || []), relation = subject.strongestRelationship;
  if (subject.matePreferences && subject.sex === "F") candidates.push(candidate(104, `social:${subject.id}:mate-preferences`, `${p} carries an individual mate-preference profile. Condition, behaviour, care, age and previous evidence can contribute separately; the profile changes assessment probability but never compels acceptance.`, "Which observed trait will matter most in the next courtship?", "A potential mate aligned with several recorded preferences may receive a more favourable assessment."));
  if (subject.mateAssessment) candidates.push(candidate(99, `social:${subject.id}:mate-assessment`, `${p} retains mating-related assessments from observed or communicated encounters. These records allow comparison through time without turning incomplete social evidence into certainty.`, "Will new courtship evidence confirm or revise the existing assessment?", "A direct encounter may outweigh an older or communicated rating."));
  if (relation?.partnerId) candidates.push(candidate(97, `social:${subject.id}:relation:${relation.partnerId}:${tidy(relation.kind)}`, `${p} has a ${tidy(relation.kind || "social")} history with ${tidy(relation.partnerId)}. Affinity, trust and familiarity remain separate records, so past contact can encourage tolerance without guaranteeing cooperation.`, "How will the recorded relationship alter their next contact?", "Positive social evidence may reduce the cost of remaining close."));
  if (subject.motherId || subject.offspring > 0 || subject.caregivers > 0) candidates.push(candidate(94, `social:${subject.id}:care-network:${subject.motherId || subject.offspring}:${subject.caregivers}`, `${p} belongs to a recorded care network${subject.motherId ? ` linked to mother ${tidy(subject.motherId)}` : ""}. Care is distributed through identifiable relationships rather than an anonymous species instinct.`, "Can the care network meet both dependent and caregiver needs?", "Resource pressure may alter how time and protection are distributed."));
  return candidates.filter(item => !recent.has(item.key)).sort((a, b) => b.score - a.score)[0] || null;
}

export function deterministicLaboratoryPassage(context = {}) {
  const candidates = [deterministicPhysiologyPassage(context), deterministicPlanningPassage(context), deterministicSocialPassage(context)].filter(Boolean);
  return candidates.sort((a, b) => b.score - a.score)[0] || null;
}

export function deterministicWorldSystemPassage(context = {}) {
  const land = context.landscape || {}, local = land.local || {}, weather = context.weatherDetail || {}, world = context.world || {}, recent = new Set(context.narrativeMemory?.recentTopics || []), candidates = [], habitat = tidy(context.habitat || "landscape");
  const rain = number(weather.rain), runoff = number(local.meanRunoff ?? land.runoff), groundwater = number(land.groundwater), discharge = number(local.meanDischarge ?? land.discharge), snow = number(land.snowPack), biomass = number(local.meanBiomass ?? land.biomass), grazing = number(land.grazingPressure), moisture = number(local.meanMoisture ?? land.moisture), flood = number(land.floodFrequency), sedimentValue = number(land.sediment);
  if (rain !== null && rain > .1 && runoff !== null && runoff > .01) candidates.push(candidate(116, `world:${habitat}:rain-runoff:${band(rain * 100)}:${band(runoff * 100)}`, `Rain over the ${habitat} is now dividing between infiltration and ${band(runoff * 100)} surface runoff. That moving fraction can join channels and alter locations beyond the present camera position after the local rainfall changes.`, "Which downstream water body will receive this runoff?", "Verified runoff may raise discharge beyond the current scene."));
  if (groundwater !== null && groundwater > 0 && (rain === null || rain < .15)) candidates.push(candidate(108, `world:${habitat}:groundwater:${band(groundwater)}`, `The ${habitat} is receiving little immediate rain, yet its groundwater store remains ${band(groundwater)}. This slower reservoir can support soil moisture, plants or springs after visible surface water has retreated.`, "How long can the underground reserve sustain the present surface conditions?", "Continued plant and channel water demand may gradually lower the recorded groundwater store."));
  if (discharge !== null && discharge > .01) candidates.push(candidate(110, `world:${habitat}:discharge:${band(discharge * 100)}`, `Measured discharge through the ${habitat} is ${band(discharge * 100)}. This flow combines water arriving from upstream with local runoff, so the channel records a wider catchment than the frame can show.`, "Is discharge still rising, or has the upstream response reached its peak?", "Upstream inflow may continue after local rain weakens."));
  if (snow !== null && snow > .02) candidates.push(candidate(109, `world:${habitat}:snow:${band(snow * 100)}:${Math.round(Number(context.temperature || 0))}`, `The ${habitat} retains a ${band(snow * 100)} snow store at a measured temperature of ${Math.round(Number(context.temperature || 0))} degrees. Snow delays the entry of precipitation into soil and channels until temperature permits melting.`, "When will this stored water re-enter the active drainage system?", Number(context.temperature) > 0 ? "Above-freezing conditions may release snowmelt into runoff and infiltration." : "Continued cold may preserve the current delayed water store."));
  if ((local.mudCells || 0) > 0 && (local.dryCells || 0) > 0) candidates.push(candidate(105, `world:${habitat}:surface-mosaic:${local.mudCells}:${local.dryCells}`, `Within the same local ${habitat}, ${local.mudCells} patches are mud while ${local.dryCells} are dry ground. Drainage, exposure and soil properties are therefore producing different movement and growth conditions over a short distance.`, "Will water movement enlarge the wet area or isolate it further?", "Local moisture differences may redirect both travel and vegetation growth."));
  if (biomass !== null && (grazing !== null || Number(local.heavilyGrazedCells) > 0)) candidates.push(candidate(107, `world:${habitat}:biomass-grazing:${band(biomass * 100)}:${band((grazing || 0) * 100)}:${local.heavilyGrazedCells || 0}`, `Plant biomass in the ${habitat} is ${band(biomass * 100)}, while ${local.heavilyGrazedCells || 0} nearby patches carry heavy grazing pressure. Growth and consumption are being measured separately, revealing whether the resource is recovering or being drawn down.`, "Can plant production replace the biomass removed here?", "Continued consumption above growth may redirect later foraging."));
  if (land.woodyStage || land.vegetationStage || local.leaflessTrees || local.fallenTrees) candidates.push(candidate(106, `world:${habitat}:succession:${tidy(land.woodyStage || land.vegetationStage)}:${local.leaflessTrees || 0}:${local.fallenTrees || 0}`, `Vegetation in the ${habitat} is recorded at the ${tidy(land.woodyStage || land.vegetationStage || "mixed")} stage, with ${local.leaflessTrees || 0} leafless and ${local.fallenTrees || 0} fallen trees nearby. Growth, standing death and ground structure are coexisting stages of succession.`, "Will present moisture and disturbance advance or reverse woodland development?", "Current water and grazing conditions may alter the next vegetation transition."));
  if (flood !== null && flood > 0) candidates.push(candidate(104, `world:${habitat}:flood-frequency:${band(flood * 100)}`, `The ${habitat} has a ${band(flood * 100)} recorded flood frequency. This is not merely a memory of exceptional water: repeated inundation helps determine soil, vegetation and the routes available here.`, "Will the next high discharge remain inside the channel?", "A sufficiently strong catchment response may return water to the floodplain."));
  if (sedimentValue !== null && sedimentValue > 0) candidates.push(candidate(101, `world:${habitat}:sediment:${band(sedimentValue * 100)}`, `The measured sediment condition in the ${habitat} is ${band(sedimentValue * 100)}. Moving water can remove material from exposed slopes and deposit it where flow slows, changing fertility and future channel form.`, "Where will the next loss of flow energy deposit this material?", "Continued runoff may redistribute sediment through the drainage network."));
  if (moisture !== null && biomass !== null) candidates.push(candidate(96, `world:${habitat}:moisture-biomass:${band(moisture * 100)}:${band(biomass * 100)}`, `Local moisture is ${band(moisture * 100)} while plant biomass is ${band(biomass * 100)}. The two records need not change together because growth also depends on season, temperature, fertility and earlier consumption.`, "Will current moisture become new growth or merely prevent further loss?", "If other constraints remain suitable, retained moisture may support later biomass growth."));
  if (world.waterCells != null && world.wetlandCells != null && world.woodlandCells != null) candidates.push(candidate(82, `world:composition:${world.waterCells}:${world.wetlandCells}:${world.woodlandCells}`, `Across the authoritative world record, ${world.waterCells} cells hold water, ${world.wetlandCells} are wetland and ${world.woodlandCells} are woodland. These areas form connected resource and movement systems rather than decorative categories.`, "Which habitat class is changing most rapidly?", "Accumulated local transitions may alter the world-scale habitat balance."));
  return candidates.filter(item => !recent.has(item.key)).sort((a, b) => b.score - a.score)[0] || null;
}
